-- ============================================================
-- V1__init.sql（PostgreSQL 方言，A6 修复）
-- 历史说明：本项目早期使用 MySQL，本脚本原为 MySQL 方言；统一迁移
-- PostgreSQL 后整体重写。Flyway 按版本号顺序执行并记录在
-- flyway_schema_history，已执行过旧版本的库不会重复执行。
-- 注意：本脚本对 application.yml 配置的目标库执行，
-- 不包含 MySQL 版的 CREATE DATABASE / USE 语句。
-- 方言对照：AUTO_INCREMENT → GENERATED BY DEFAULT AS IDENTITY；
--          DATETIME → TIMESTAMP；LONGTEXT → TEXT；
--          去掉 ENGINE/CHARSET 与反引号；ON UPDATE CURRENT_TIMESTAMP
--          在 PG 中不存在，update_time 由应用层维护。
-- ============================================================

-- "user" 是 PostgreSQL/ANSI 保留字，必须带引号；
-- 应用侧已配置 hibernate.auto_quote_keyword=true 保持与实体映射一致
CREATE TABLE IF NOT EXISTS "user" (
    id            BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    username      VARCHAR(50)  NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    email         VARCHAR(100),
    create_time   TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_time   TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS user_api_key (
    id            BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    user_id       BIGINT NOT NULL,
    provider      VARCHAR(20) NOT NULL,
    encrypted_key TEXT NOT NULL,
    key_alias     VARCHAR(50),
    create_time   TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_time   TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_user_provider ON user_api_key (user_id, provider);

CREATE TABLE IF NOT EXISTS chat_session (
    id          BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    user_id     BIGINT NOT NULL,
    title       VARCHAR(100),
    create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_chat_session_user ON chat_session (user_id);

CREATE TABLE IF NOT EXISTS chat_message (
    id          BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    user_id     BIGINT NOT NULL,
    session_id  BIGINT NOT NULL,
    role        VARCHAR(20) NOT NULL,
    content     TEXT NOT NULL,
    tool_name   VARCHAR(50),
    create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_chat_message_session ON chat_message (session_id);

